<?php
namespace App\Services\Invoices;
use App\Models\Invoice; use App\Models\Product; use Illuminate\Support\Facades\DB;
class InvoiceService { public function create(array $data,$user):Invoice{return DB::transaction(function()use($data,$user){$invoice=Invoice::create(['company_id'=>$user->company_id,'branch_id'=>$data['branch_id']??$user->branch_id,'client_id'=>$data['client_id'],'sale_id'=>$data['sale_id']??null,'user_id'=>$user->id,'invoice_number'=>$this->number($user->company_id),'issue_date'=>$data['issue_date']??today(),'due_date'=>$data['due_date']??null,'status'=>'issued','subtotal'=>0,'discount'=>$data['discount']??0,'tax'=>0,'total'=>0,'amount_paid'=>0,'balance'=>0,'notes'=>$data['notes']??null]);$subtotal=0;$tax=0;foreach($data['items'] as $item){$p=!empty($item['product_id'])?Product::where('company_id',$user->company_id)->find($item['product_id']):null;$qty=(float)$item['quantity'];$price=(float)$item['unit_price'];$discount=(float)($item['discount']??0);$line=max(0,$qty*$price-$discount);$rate=$item['tax_rate']??($p?->tax_rate??0);$lineTax=$line*((float)$rate/100);$invoice->items()->create(['product_id'=>$p?->id,'description'=>$item['description']??($p?->name??'Item'),'quantity'=>$qty,'unit_price'=>$price,'discount'=>$discount,'tax'=>$lineTax,'total'=>$line+$lineTax]);$subtotal+=$qty*$price;$tax+=$lineTax;}$discount=(float)($data['discount']??0);$total=max(0,$subtotal-$discount+$tax);$invoice->update(['subtotal'=>$subtotal,'tax'=>$tax,'total'=>$total,'balance'=>$total]);return $invoice->load('items.product','client');});}private function number($companyId):string{$n=Invoice::where('company_id',$companyId)->count()+1;return 'INV-'.str_pad((string)$n,6,'0',STR_PAD_LEFT);}}
